            continue

        # 1) eliminate one bin
        order_bins = sorted(range(len(bins)), key=lambda b: loads[b])
        for target in order_bins:
            if not bins[target]:
                continue
            other_bins = [b for b in range(len(bins)) if b != target and bins[b]]
            if not other_bins:
                continue
            target_items = bins[target][:]
            total_res = sum(cap - loads[b] for b in other_bins)
            if loads[target] > total_res:
                continue
            for limit in (5000, 20000, 50000):
                res = try_redistribute(target_items, other_bins, loads, cap, deadline, max_nodes=limit)
                if res is not None:
                    for item_idx, j in res:
                        b = other_bins[j]
                        bins[b].append(item_idx)
                        loads[b] += items[item_idx]
                    bins[target] = []
                    loads[target] = 0
                    new_bins = []
                    new_loads = []
                    for b in range(len(bins)):
                        if bins[b]:
                            new_bins.append(bins[b])
                            new_loads.append(loads[b])
                    bins, loads = new_bins, new_loads
                    improved = True
                    break
            if improved:
                break
        if improved:
            continue

        # 2) repack m bins into m-1
        order_bins = sorted(range(len(bins)), key=lambda b: loads[b])
        limit = min(len(order_bins), 10)
        for m in (3, 4, 5):
            if time.perf_counter() > deadline:
                break
            found = False
            for combo in itertools.combinations(order_bins[:limit], m):
                if time.perf_counter() > deadline:
                    break
                total_load = sum(loads[b] for b in combo)
                if total_load > (m - 1) * cap:
                    continue
                combined_items = []
                for b in combo:
                    combined_items.extend(bins[b])
                res = exact_pack_items(combined_items, m - 1, deadline, max_nodes=5000)
                if res is not None and len(res) <= m - 1:
                    new_bins = []
                    new_loads = []
                    combo_set = set(combo)
                    for b in range(len(bins)):
                        if b not in combo_set:
                            new_bins.append(bins[b])
                            new_loads.append(loads[b])
                    for bin_items in res:
                        new_bins.append(bin_items)
                        new_loads.append(sum(items[i] for i in bin_items))
                    bins, loads = new_bins, new_loads
                    improved = True
                    found = True
                    break
            if found:
                break
        if improved:
            continue

        # 3) exact whole problem if n small
        if n <= 60 and time.perf_counter() < deadline:
            K = len(bins) - 1
            res = exact_pack_items(list(range(n)), K, min(deadline, time.perf_counter() + 0.2), max_nodes=100000)
            if res is not None:
                bins = res
                loads = [sum(items[i] for i in b) for b in bins]
                improved = True
                if len(bins) == lb:
                    break
        if not improved:
            break

    result = [b for b in bins if b]
    seen = set()
    valid = True
    for b in result:
        load = 0
        for i in b:
            if i < 0 or i >= n or i in seen:
                valid = False
                break
            seen.add(i)
            load += items[i]
        if load > cap:
            valid = False
            break
    if not valid or len(seen) != n:
        b, _ = ffd()
        return b
    return result
